    11→# Pure SPPF Element - only tracks forest structure, no scoring
    12→class Chalk::Semiring::SPPFElement :isa(Chalk::Element) {
    13→    field $sppf_node :param :reader;
    14→    field $forest    :param :reader;
    15→
    16→    method multiply( $other, $swap = undef ) {
    17→        # Create new combined SPPF node representing sequence
    18→        my $other_node = $other->sppf_node();
    19→        my $combined_node =
    20→          $forest->create_sequence_node( $sppf_node, $other_node );
    21→
    22→        return Chalk::Semiring::SPPFElement->new(
    23→            sppf_node => $combined_node,
    24→            forest    => $forest
    25→        );
    26→    }
    27→
    28→    method add( $other, $swap = undef ) {
    29→        my $self_start = $sppf_node->start_pos();
    30→        my $self_end = $sppf_node->end_pos();
    31→        my $other_node = $other->sppf_node();
    32→        my $other_start = $other_node->start_pos();
    33→        my $other_end = $other_node->end_pos();
